/**
 * Realtime slice — SDP negotiator (ADR-0230).
 *
 * Pure function. Parses a minimal SDP offer (RFC 4566 surface only — we
 * inspect `v=`, `o=`, and `m=audio` lines) and produces an SDP answer that
 * mirrors the offered codec (HELL-RT-17). The function does NOT own a
 * `RTCPeerConnection` — the surface uses the answer to build its own peer
 * connection if it wants actual media.
 *
 * Why text-level only:
 *   - The full SDP grammar is ~30 line types; real WebRTC SDP gets
 *     generated by `RTCPeerConnection.createOffer()` and validated by
 *     `setRemoteDescription()`. This slice is the absorb-the-surface MVP
 *     — the negotiate handshake is text-level so the port stays leaf and
 *     testable, and the surface picks its codec without bundling
 *     `libwebrtc`.
 *   - The marker preservation (PCM/Opus) IS load-bearing: it's the only
 *     thing surfaces use from the answer when wiring their own
 *     `RTCPeerConnection.setRemoteDescription(answer)`.
 *
 * Plane-clean: imports only `@/shared`.
 */

import { err, ok, type Result } from "@/shared"
import type { AudioCodec, RealtimeError, SdpAnswer } from "./types"

const SDP_VERSION_LINE = "v=0"
const SDP_ORIGIN_PREFIX = "o="
const SDP_AUDIO_MEDIA_PREFIX = "m=audio"

/**
 * Codec inference from a single SDP offer line.
 *
 * Real SDP encodes codecs via `a=rtpmap:N codec/rate` lines (e.g.
 * `a=rtpmap:111 opus/48000/2`). We scan rtpmaps in order and return the
 * FIRST recognized codec — surfaces relying on negotiator order match
 * how `RTCPeerConnection` picks its preferred codec.
 */
const inferCodecFromOffer = (offer: string): AudioCodec => {
  for (const line of offer.split(/\r?\n/)) {
    const trimmed = line.trim().toLowerCase()
    if (!trimmed.startsWith("a=rtpmap:")) continue
    if (trimmed.includes("opus/")) return "opus"
    if (trimmed.includes("pcm") || trimmed.includes("pcmu") || trimmed.includes("pcma")) {
      return "pcm"
    }
  }
  // Default when no explicit rtpmap survives: PCM (the universal fallback
  // every endpoint supports — matches Codex absorption behavior).
  return "pcm"
}

/**
 * Negotiate a single offer/answer exchange.
 *
 * Returns `Err({kind:"empty-sdp"})` on empty input (HELL-RT-18) and
 * `Err({kind:"invalid-sdp"})` when the offer is missing required `v=0` /
 * `o=` / `m=audio` lines (HELL-RT-06). Otherwise returns an answer that
 * mirrors the offer's codec (HELL-RT-17).
 */
export const negotiateSdp = (sdpOffer: string): Result<SdpAnswer, RealtimeError> => {
  if (sdpOffer.length === 0) return err({ kind: "empty-sdp" })

  const lines = sdpOffer.split(/\r?\n/).map((l) => l.trim())
  const hasVersion = lines.some((l) => l === SDP_VERSION_LINE)
  const hasOrigin = lines.some((l) => l.startsWith(SDP_ORIGIN_PREFIX))
  const hasAudio = lines.some((l) => l.startsWith(SDP_AUDIO_MEDIA_PREFIX))

  if (!hasVersion) {
    return err({ kind: "invalid-sdp", degradeReason: "missing v=0 line" })
  }
  if (!hasOrigin) {
    return err({ kind: "invalid-sdp", degradeReason: "missing o= line" })
  }
  if (!hasAudio) {
    return err({ kind: "invalid-sdp", degradeReason: "missing m=audio line" })
  }

  const codec = inferCodecFromOffer(sdpOffer)
  // Minimal answer SDP — version + origin + media + rtpmap echoing codec.
  // Surfaces that need full SDP for their own RTCPeerConnection will
  // augment this; the test pin only requires v=0 + matching codec marker.
  const sessionId = String(Date.now())
  const codecLine = codec === "opus" ? "a=rtpmap:111 opus/48000/2" : "a=rtpmap:0 PCMU/8000"
  const codecPayload = codec === "opus" ? "111" : "0"
  const answer = [
    "v=0",
    `o=- ${sessionId} 1 IN IP4 0.0.0.0`,
    "s=-",
    "t=0 0",
    `m=audio 9 UDP/TLS/RTP/SAVPF ${codecPayload}`,
    codecLine,
  ].join("\r\n")

  return ok({ sdp: answer, codec })
}
